changeSet.sql:
SET QUOTED_IDENTIFIER ON;
IF EXISTS (SELECT 1 FROM sys.check_constraints WHERE name = N'CK_Notifications_Type' AND parent_object_id = OBJECT_ID(N'app.Notifications'))
    ALTER TABLE app.Notifications DROP CONSTRAINT CK_Notifications_Type;
ALTER TABLE app.Notifications ADD CONSTRAINT CK_Notifications_Type CHECK (Type IN (N'WorkoutReminder', N'MembershipReminder', N'ChallengeReminder', N'AiRecommendation', N'WorkoutCompleted', N'StaffLeaveUpdate', N'ChatMessage', N'WorkoutPlanUpdated', N'TrainerAssigned', N'ProgressMilestone', N'CircularPublished'));
